import{z as l,x as A,o,c as d,q as r,j as i,D as e,d as t,s as n,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"光刻胶雾化","description":"","frontmatter":{"title":"光刻胶雾化","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-fogs.md","filePath":"litho/resist-fogs.md","lastUpdated":1791063341000}'),g={name:"litho/resist-fogs.md"};function p(f,E,D,m,h,c){const s=A("Mermaid");return o(),d("div",null,[E[2]||(E[2]=r('<h1 id="光刻胶雾化" tabindex="-1">光刻胶雾化 <a class="header-anchor" href="#光刻胶雾化" aria-label="Permalink to &quot;光刻胶雾化&quot;">​</a></h1><div class="epigraph"><p>不该曝光的地方莫名曝光了：EUV 的杂散光子在真空腔里弹来弹去——雾化（fogging）是整套系统的影子税。</p><footer>—— 据 EUV fogging 与杂散光文献（ASML/Zeiss）；IEC/SEMI EUV 掩模规范讨论</footer></div><p><a href="/litho/offner-relay">Offner 中继</a>讲成像光学的主路，本课讲主路之外的光：<strong>光刻胶雾化</strong>——设计图形之外的区域被杂散 EUV 曝光，隐约显影、悄悄改形。它是 EUV 独有的系统级副产物：多层膜反射率不到 70%，每一次反射都漏光，漏掉的光在腔内多次弹射后落在「不该在的地方」。本课不做杂散光的辐射输运计算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三种来源汇成雾。<strong>掩模外反射</strong>：EUV 掩模的多层膜在图形区外是全反射面，反射的杂散光进入投影光路。<strong>真空腔弹射</strong>：从掩模/晶圆散射的光在反射镜组、腔壁间多次反射，一部分落在晶圆上，无方向性、长程。<strong>光电子与二次电子</strong>：EUV 光子在胶中打出光电子，电子迁移范围数十纳米——邻近图形的「电子串扰」。缺口：量化雾化的空间结构与对策。</p><p><span class="marginnote">术语翻译：fogging（雾化）= 长程杂散光造成的均匀底曝光； flare（炫光）= 光学系统的短程杂散；out-of-band（OOB，带外光）= 光源里混入的 DUV 成分，反射镜对它不拦；electron blur = 光电子/二次电子的迁移模糊。</span></p><p><span class="marginnote">数字实例：掩模反射率 ~65%、每个反射镜 ~64.4%，7 镜投影 + 掩模 = 8 次反射，到晶圆的能量只有入射的 ~3%；其余 98% 变成腔内杂散能量，其中一部分返回晶圆成为 fog——多层膜反射率每提升 1%，雾化预算就松动一大截。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对策按「来源→路径→受体」分层。<strong>源头</strong>：掩模黑边（black border / LTEM 吸收材料）与 mask backside coating 压掉图形外反射；带外滤镜（spectral purity filter, SPF）拦 OOB。<strong>路径</strong>：腔壁黑化涂层、挡板与快门设计减少弹射次数；投影光学的 flare 指标逐代收紧。<strong>受体</strong>：胶侧抗雾化设计（更快的显影对比度让底曝光不显影）、OPC 里把 fog 当背景剂量建模进校准、曝光后烘烤参数调优。计量：用「开放图形 + 大块暗区」的测试掩模测雾化分布，进 dose map 补偿。</p>',9)),(o(),i(B,null,{default:e(()=>[n(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%BA%90%E5%A4%B4%3A%20%E6%8E%A9%E6%A8%A1%E9%BB%91%E8%BE%B9%20%2B%20SPF%20%E6%BB%A4%E5%B8%A6%E5%A4%96%22%5D%20--%3E%20B%5B%22%E5%B0%91%E4%BA%A7%E6%9D%82%E6%95%A3%E5%85%89%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%B7%AF%E5%BE%84%3A%20%E8%85%94%E5%A3%81%E9%BB%91%E5%8C%96%2F%E6%8C%A1%E6%9D%BF%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%8F%97%E4%BD%93%3A%20%E8%83%B6%E5%AF%B9%E6%AF%94%E5%BA%A6%20%2B%20OPC%20%E5%BB%BA%20fog%22%5D%0A%20%20D%20--%3E%20E%5B%22%E8%AE%A1%E9%87%8F%3A%20%E6%B5%8B%E9%9B%BE%E5%8C%96%20%E2%86%92%20dose%20map%20%E8%A1%A5%E5%81%BF%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%9B%BE%E5%8C%96%E8%BF%9B%E9%A2%84%E7%AE%97%2C%20%E8%89%AF%E7%8E%87%E5%9B%9E%E7%AC%BC%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：像深夜房间里开着一台强光手电——就算灯头朝墙（掩模黑边），白墙（多层膜）照样把光弹得满屋都是（腔内弹射）；对策是墙刷成黑色（黑化涂层）、手电加滤光片（SPF）、眼睛适应暗处（胶对比度），最后还要给房间「暗角手动补光」（dose map 补偿）。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"长程机制：腔内光子经镜面散射与腔壁反射形成「均匀底 + 缓变梯度」的剂量本底，它直接吃掉 dose-to-size 窗口的下边——雾化强的地方名义剂量要整体下调，窗口变窄。短程机制（electron blur）：EUV 光电子在胶中迁移 10–50nm，邻近图形边缘获得亚分辨率剂量的「晕」——LER 与 CD 偏置的隐性来源，且随特征间距缩小非线性加重。带外机制：光源的 DUV 成分不被多层膜拦截（反射镜对 13.5nm 之外不挑），直接穿过系统曝光胶的 DUV 响应——SPF 滤片以透光损失换纯净度，又是预算里的一笔汇率。三者叠加的后果：EUV 的「有效剂量窗口」比理论窄，fogging 校准成为工艺整合的固定动作。",-1)),(o(),i(B,null,{default:e(()=>[n(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E9%9B%BE%E5%90%83%E6%8E%89%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%7C%22%E9%95%BF%E7%A8%8B%E5%BA%95%E6%9B%9D%E5%85%89%22%7C%20R%5B%22dose%20%E7%AA%97%E5%8F%A3%E4%B8%8B%E8%BE%B9%E5%8F%98%E7%AA%84%22%5D%0A%20%20Q%20--%3E%7C%22%E7%94%B5%E5%AD%90%E6%99%95%22%7C%20S%5B%22LER%2FCD%20%E9%9A%90%E6%80%A7%E5%81%8F%E7%BD%AE%22%5D%0A%20%20Q%20--%3E%7C%22OOB%20%E7%9B%B4%E7%A9%BF%22%7C%20T%5B%22DUV%20%E5%81%87%E6%9B%9D%E5%85%89%22%5D%0A%20%20R%20--%3E%20U%5B%22%E5%90%8D%E4%B9%89%E5%89%82%E9%87%8F%E6%95%B4%E4%BD%93%E4%B8%8B%E8%B0%83%22%5D%0A%20%20S%20--%3E%20V%5B%22%E9%97%B4%E8%B7%9D%E7%BC%A9%E5%B0%8F%E9%9D%9E%E7%BA%BF%E6%80%A7%E5%8A%A0%E9%87%8D%22%5D%0A%20%20T%20--%3E%20W%5B%22SPF%3A%20%E9%80%8F%E5%85%89%E6%8D%A2%E7%BA%AF%E5%87%80%22%5D%0A%20%20U%20--%3E%20X%5B%22%E6%9C%89%E6%95%88%E7%AA%97%E5%8F%A3%20%3D%20%E7%90%86%E8%AE%BA%20%E2%88%92%20%E9%9B%BE%22%5D%0A%20%20V%20--%3E%20X%0A%20%20W%20--%3E%20X%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：把 fogging 与 flare 混用——flare 是光学系统近场杂散、随光圈结构变化，fogging 是腔级长程本底+电子晕，对策不同；另一误区是「黑边贴上就完事」——黑边材料的反射率与边缘散射仍非零，黑边宽度本身要进 OPC 模型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>雾化对图形密度的敏感性使它与<a href="/litho/dummy-fill-density">虚拟填充与密度规则</a>再度相遇：填充图形改变局部散射环境，fog 模型要按密度分层校准。High-NA 的变化：成像光路减少一面镜（7→6），效率提升让杂散能量比例下降——但数值孔径增大让电子晕相对特征尺寸的占比上升，短程机制反而吃紧。检测端：雾化在 EUV 掩模缺陷检测（actinic）里是底噪的重要成分，检测工具自己的 fog 管理决定最小可检缺陷。与<a href="/litho/euv-dose-budget">EUV 剂量预算</a>的关系收束：雾是「看不见的剂量支出」，剂量预算表里必须给它留一行。</p><p><span class="marginnote">直觉类比：雾化像「全屋的背景噪音」——长程雾是空调的嗡嗡底噪（均匀、吃掉听力余量），电子晕是邻座耳语（近距离、越来越烦），带外光是隔壁装修的电钻（完全不同的频段、直接穿透）；房子的「安静标准」（剂量窗口）要同时给三者扣分。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>雾化三源：掩模/腔弹射的长程本底、光电子晕、带外直穿。</li><li>代价统一表现为剂量窗口变窄；对策分源头/路径/受体三层。</li><li>High-NA 长程改善、短程吃紧；检测工具的底噪也由它定。</li><li>出处：ASML/Zeiss 杂散光文献；imec EUV stochastics 研究；SEMI EUV 掩模规范讨论稿。</li></ul>',6))])}const C=l(g,[["render",p]]);export{F as __pageData,C as default};
